"""Render the evidence-backed Markdown narrative; all table numbers come from CSV."""
from study import *
from figures import LABELS

DOC=ROOT/'docs/research/uptrend-extension-2026-10-29'
LINK='uptrend-extension-2026-10-29/'

def table(headers,rows):
    esc=lambda x:str(x).replace('|','\\|')
    return '| '+' | '.join(map(esc,headers))+' |\n| '+' | '.join(['---']*len(headers))+' |\n'+''.join('| '+' | '.join(map(esc,r))+' |\n' for r in rows)+'\n'

def pc(v,d=1):return f'{100*v:.{d}f}'
def interval(v,lo,hi):return f'{pc(v)} [{pc(lo)}, {pc(hi)}]'
def effect(v,lo,hi):return f'{100*v:+.2f} [{100*lo:+.2f}, {100*hi:+.2f}]'
def link(name,label=None):return f'[{label or name}]({LINK}{name})'

