    # Readability only; preserve indicator IDs, file links and commit hashes.
    words='completed|evaluated|plus|with|at|only|from|of|and|the|bar|was|is|all|about|rates|ending|contains|periods|retains|below|cover|over|before|after|mean|median|next|through|within|include|uses|to|are|exactly|controls|requires|least|schemes|cut|another|epoch|original|Scheme|scheme|age|ages|overlapping|first|by|through|since|day|bars|adds|returns|strict|simultaneous|their|held|supply|correction|horizons'
    prose=re.sub(r'\b('+words+r')(?=\d)',r'\1 ',prose,flags=re.I).replace('KR:21','KR: 21').replace('US:21','US: 21')
    target=ROOT/'docs/research/uptrend-extension-2026-10-29.md';target.write_text(prose,encoding='utf-8')
    print('Report saved',target.stat().st_size,'bytes',flush=True)

